(6790898, 1019303, 147314, '<td valign="top">Love the idea of red on black and white, but the contrast between red flower and background should be more distinctive. Therefore a 8 for the idea, but a 6 for the final result.</td>', 'Love the idea of red on black and white, but the contrast between red flower and background should be more distinctive. Therefore a 8 for the idea, but a 6 for the final result.', '2012-06-09 06:21:04.000000', NULL, 1),
(6790899, 1019812, 147314, '<td valign="top">Really like the coloured border; gives the picture an extra dimension. Well done!</td>', 'Really like the coloured border; gives the picture an extra dimension. Well done!', '2012-06-09 06:21:56.000000', NULL, 1),
(6790900, 1019291, 147314, '<td valign="top">Really great picture with the focus on the flowers and the shoulders a bit vague.</td>', 'Really great picture with the focus on the flowers and the shoulders a bit vague.', '2012-06-09 06:23:41.000000', NULL, 1),
(6790901, 1019253, 147314, '<td valign="top">Great shot, really love the colour and the sharpness of the picture.</td>', 'Great shot, really love the colour and the sharpness of the picture.', '2012-06-09 06:25:53.000000', NULL, 1),
(6790902, 1019225, 147314, '<td valign="top">Great picture, lovely colours and a a great blurred out background.</td>', 'Great picture, lovely colours and a a great blurred out background.', '2012-06-09 06:29:48.000000', NULL, 1),
(6790903, 1019718, 147314, '<td valign="top">Beautiful picture, great overall sharpness and lovely colours against a dark blackground</td>', 'Beautiful picture, great overall sharpness and lovely colours against a dark blackground', '2012-06-09 06:32:13.000000', NULL, 1),
